  "help.document.after-sales-spare-requisition.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.after-sales-spare-requisition.overview.title": "1. 概述",
  "help.document.after-sales-spare-requisition.push.alert": "下推按钮置灰时，将鼠标悬停可查看具体原因（未审核、模块未启用、无权限、无可推数量等）。",
  "help.document.after-sales-spare-requisition.push.b1": "下推派工单。",
  "help.document.after-sales-spare-requisition.push.b2": "下推维修单。",
  "help.document.after-sales-spare-requisition.push.b3": "关联备件领用。",
  "help.document.after-sales-spare-requisition.push.b4": "服务结算。",
  "help.document.after-sales-spare-requisition.push.b5": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.after-sales-spare-requisition.push.b6": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.after-sales-spare-requisition.push.b7": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.after-sales-spare-requisition.push.b8": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.after-sales-spare-requisition.push.label": "5.4 下推与下游单据",
  "help.document.after-sales-spare-requisition.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.after-sales-spare-requisition.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.after-sales-spare-requisition.push.title": "5.4 下推与下游单据",
  "help.document.after-sales-spare-requisition.search.b1": "关键词：模糊匹配单号、编码、名称等主字段。",
