  "help.document.document-reconciliation.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.document-reconciliation.detail.title": "5.6 详情抽屉与行操作",
  "help.document.document-reconciliation.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.document-reconciliation.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.document-reconciliation.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效单据对账。",
  "help.document.document-reconciliation.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.document-reconciliation.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.document-reconciliation.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
  "help.document.document-reconciliation.faq.q1": "Q: 为什么下推或审核按钮是灰的？",
