  "help.document.document-reconciliation.faq.q5": "Q: 明细视图为什么不能批量操作？",
  "help.document.document-reconciliation.faq.q6": "Q: 看不到某工具栏按钮？",
  "help.document.document-reconciliation.guide.label": "5. 操作指南",
  "help.document.document-reconciliation.layout.b1": "指标卡：待处理、逾期等快照（若有）。",
  "help.document.document-reconciliation.layout.b2": "工具栏：新建/取单、下推（需选中单条）、批量审核、打印、导入导出等。",
