  "help.document.document-reconciliation.views.orderB3": "生命周期、执行进度在单据级展示。",
  "help.document.document-reconciliation.views.orderP1": "一行一张单据对账，适合批量审核、下推、关单与跟单。",
  "help.document.document-reconciliation.views.orderTitle": "表头视图（默认）",
  "help.document.document-reconciliation.views.p1": "两种视图服务不同工作场景，可随时切换对比。",
  "help.document.document-reconciliation.views.title": "5.2 表头视图与明细视图",
  "help.document.document-reconciliation.workflow.label": "2. 典型业务流程",
  "help.document.document-reconciliation.workflow.p1": "以下为常见路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.document-reconciliation.workflow.s1": "新建单据对账：空白新建或从上游单据取单带入头行。",
  "help.document.document-reconciliation.workflow.s2": "维护行项目：确认物料、数量、仓库等必填项，保存草稿或提交审核。",
  "help.document.document-reconciliation.workflow.s3": "审核通过：单据进入执行态，可进行下推或过账类操作（若适用）。",
  "help.document.document-reconciliation.workflow.s4": "执行：按业务流程完成收货、发运、检验或财务处理。",
  "help.document.document-reconciliation.workflow.s5": "异常处理：驳回、撤回或走变更/冲销通道（若组织启用）。",
  "help.document.document-reconciliation.workflow.s6": "关单：业务完成后关单，冻结后续下推。",
  "help.document.document-reconciliation.workflow.title": "2. 典型业务流程",
  "help.document.eight-d-report.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.eight-d-report.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
