  "help.document.equipment-transfers.layout.b2": "工具栏：新建/取单、下推（需选中单条）、批量审核、打印、导入导出等。",
  "help.document.equipment-transfers.layout.b3": "列表列：单号叠列伙伴/物料、进度与右侧固定状态；行操作提供查看、编辑、审核等。",
  "help.document.equipment-transfers.layout.b4": "交期或到期类高亮以页面实际配置为准。",
  "help.document.equipment-transfers.layout.label": "3. 页面布局",
  "help.document.equipment-transfers.layout.p1": "页面自上而下分为指标区（若有）、工具栏与列表区；右上角可切换表头/明细/帮助视图。",
  "help.document.equipment-transfers.layout.title": "3. 页面布局",
  "help.document.equipment-transfers.lifecycle.auditB1": "草稿：可编辑、可删除（有权限时）。",
  "help.document.equipment-transfers.lifecycle.auditB2": "待审核：等待审批人处理，通常不可直接下推。",
  "help.document.equipment-transfers.lifecycle.auditB3": "已审核：可下推、可打印，修改需走正式变更通道。",
  "help.document.equipment-transfers.lifecycle.auditP1": "是否启用多级审核由组织配置决定；行内按钮可能显示提交、通过、驳回、撤回等。",
  "help.document.equipment-transfers.lifecycle.auditTitle": "审核相关",
  "help.document.equipment-transfers.lifecycle.closeB1": "批量关单前请确认无进行中的下游作业。",
  "help.document.equipment-transfers.lifecycle.closeB2": "误关单且业务允许时，可使用批量重开恢复执行态。",
  "help.document.equipment-transfers.lifecycle.closeP1": "关单表示业务终止或已全部执行完毕，关单后通常不可再下推。",
