  "help.document.equipment-transfers.lifecycle.label": "5.5 状态与审核",
  "help.document.equipment-transfers.lifecycle.p1": "右侧「生命周期」或状态列展示当前阶段，与行内审核按钮联动。",
  "help.document.equipment-transfers.lifecycle.title": "5.5 状态与审核",
  "help.document.equipment-transfers.overview.b1": "记录设备调拨业务数据，作为下游流程的依据。",
  "help.document.equipment-transfers.overview.b2": "关联设备台账，执行记录回写设备状态与履历。",
  "help.document.equipment-transfers.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.equipment-transfers.overview.b4": "工具栏提供新建、批量与导入导出（以权限为准）。",
  "help.document.equipment-transfers.overview.label": "1. 概述",
  "help.document.equipment-transfers.overview.p1": "设备调拨在厂区或部门间转移设备台账归属。",
  "help.document.equipment-transfers.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.equipment-transfers.overview.title": "1. 概述",
