  "help.document.exception-delivery-delay.faq.q3": "Q: 已审核单据如何修改？",
  "help.document.exception-delivery-delay.faq.q4": "Q: 导入失败常见原因？",
  "help.document.exception-delivery-delay.faq.q5": "Q: 明细视图为什么不能批量操作？",
  "help.document.exception-delivery-delay.faq.q6": "Q: 看不到某工具栏按钮？",
