  "help.document.exception-process.layout.b1": "指标卡：待处理、逾期等快照（若有）。",
  "help.document.exception-process.layout.b2": "工具栏：刷新、导出、批量关闭（以权限为准）。",
  "help.document.exception-process.layout.b3": "列表列：单号叠列伙伴/物料、进度与右侧固定状态；行操作提供查看、编辑、审核等。",
  "help.document.exception-process.layout.b4": "交期或到期类高亮以页面实际配置为准。",
  "help.document.exception-process.layout.label": "3. 页面布局",
  "help.document.exception-process.layout.p1": "页面自上而下分为指标区（若有）、工具栏与列表区；右上角可切换表头/明细/帮助视图。",
  "help.document.exception-process.layout.title": "3. 页面布局",
