  "help.document.exception-process.lifecycle.auditTitle": "审核相关",
  "help.document.exception-process.lifecycle.closeB1": "批量关单前请确认无进行中的下游作业。",
  "help.document.exception-process.lifecycle.closeB2": "误关单且业务允许时，可使用批量重开恢复执行态。",
  "help.document.exception-process.lifecycle.closeP1": "关单表示业务终止或已全部执行完毕，关单后通常不可再下推。",
