  "help.document.exception-process.lifecycle.label": "5.5 状态与审核",
  "help.document.exception-process.lifecycle.p1": "右侧「生命周期」或状态列展示当前阶段，与行内审核按钮联动。",
  "help.document.exception-process.lifecycle.title": "5.5 状态与审核",
  "help.document.exception-process.overview.b1": "记录异常处理业务数据，作为下游流程的依据。",
  "help.document.exception-process.overview.b2": "支持表头/明细视图切换，满足不同岗位核对习惯。",
  "help.document.exception-process.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.exception-process.overview.b4": "工具栏提供新建、批量与导入导出（以权限为准）。",
  "help.document.exception-process.overview.label": "1. 概述",
  "help.document.exception-process.overview.p1": "集中处理生产异常工单与关闭流程。",
  "help.document.exception-process.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.exception-process.overview.title": "1. 概述",
  "help.document.exception-process.push.alert": "下推按钮置灰时，将鼠标悬停可查看具体原因（未审核、模块未启用、无权限、无可推数量等）。",
  "help.document.exception-process.push.b1": "关联工单或订单。",
  "help.document.exception-process.push.b2": "记录处置结论。",
  "help.document.exception-process.push.b3": "关闭异常。",
  "help.document.exception-process.push.b4": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.exception-process.push.b5": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.exception-process.push.b6": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.exception-process.push.b7": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.exception-process.push.b8": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.exception-process.push.label": "5.4 下推与下游单据",
  "help.document.exception-process.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.exception-process.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.exception-process.push.title": "5.4 下推与下游单据",
  "help.document.exception-process.search.b1": "关键词：模糊匹配单号、编码、名称等主字段。",
  "help.document.exception-process.search.b2": "工单/订单：按来源单号筛选。",
  "help.document.exception-process.search.b3": "业务日期范围：按单据日期或计划日期过滤。",
  "help.document.exception-process.search.b4": "生命周期/状态：筛选草稿、待审核、执行中、已关单等。",
  "help.document.exception-process.search.b5": "高级搜索：展开更多条件（含自定义字段，若已配置）。",
  "help.document.exception-process.search.b6": "点击指标卡：快速跳转到对应状态集合。",
  "help.document.exception-process.search.label": "4. 查询与筛选",
  "help.document.exception-process.search.p1": "表头视图与明细视图共用同一套筛选条件，切换视图不会丢失已填条件。",
  "help.document.exception-process.search.title": "4. 查询与筛选",
  "help.document.exception-process.views.detailB1": "只读查看，不可在此视图直接编辑行。",
  "help.document.exception-process.views.detailB2": "无行勾选时，批量操作请切回表头视图。",
  "help.document.exception-process.views.detailB3": "分页按行计数，与表头视图总数可能不同属正常现象。",
  "help.document.exception-process.views.detailP1": "一行一条行项目，适合按物料核对数量与执行进度。",
  "help.document.exception-process.views.detailTitle": "明细视图",
  "help.document.exception-process.views.label": "5.2 表头视图与明细视图",
  "help.document.exception-process.views.orderB1": "可展开行查看行项目摘要（若启用展开）。",
  "help.document.exception-process.views.orderB2": "支持多选批量操作与工具栏下推（选中单条时）。",
  "help.document.exception-process.views.orderB3": "生命周期、执行进度在单据级展示。",
  "help.document.exception-process.views.orderP1": "一行一张异常处理，适合批量审核、下推、关单与跟单。",
  "help.document.exception-process.views.orderTitle": "表头视图（默认）",
  "help.document.exception-process.views.p1": "两种视图服务不同工作场景，可随时切换对比。",
  "help.document.exception-process.views.title": "5.2 表头视图与明细视图",
  "help.document.exception-process.workflow.label": "2. 典型业务流程",
  "help.document.exception-process.workflow.p1": "以下为常见路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.exception-process.workflow.s1": "新建异常处理：空白新建或从上游单据取单带入头行。",
  "help.document.exception-process.workflow.s2": "维护行项目：确认物料、数量、仓库等必填项，保存草稿或提交审核。",
  "help.document.exception-process.workflow.s3": "审核通过：单据进入执行态，可进行下推或过账类操作（若适用）。",
  "help.document.exception-process.workflow.s4": "执行：按业务流程完成收货、发运、检验或财务处理。",
  "help.document.exception-process.workflow.s5": "异常处理：驳回、撤回或走变更/冲销通道（若组织启用）。",
  "help.document.exception-process.workflow.s6": "关单：业务完成后关单，冻结后续下推。",
  "help.document.exception-process.workflow.title": "2. 典型业务流程",
  "help.document.fai-order.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.fai-order.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.fai-order.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.fai-order.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.fai-order.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.fai-order.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.fai-order.batch.label": "5.3 工具栏与批量操作",
  "help.document.fai-order.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.fai-order.batch.title": "5.3 工具栏与批量操作",
  "help.document.fai-order.create.b1": "空白新建：适用于无上游单据的零星首件检验。",
  "help.document.fai-order.create.b2": "导入：按模板批量创建，导入前请确认主数据编码已存在。",
  "help.document.fai-order.create.b3": "已审核单据修改通常需走变更单或冲销流程，勿直接改已生效数据。",
  "help.document.fai-order.create.label": "5.1 新建与取单",
  "help.document.fai-order.create.p1": "关联工单与工序，记录首件测量数据。",
  "help.document.fai-order.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
  "help.document.fai-order.create.s2": "在取单弹窗中筛选来源单据行，确认带入头行信息。",
  "help.document.fai-order.create.s3": "在表单中补全仓库、数量、日期等必填项，检查行单位与数量。",
  "help.document.fai-order.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
