  "help.document.fai-order.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.fai-order.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.fai-order.detail.label": "5.6 详情抽屉与行操作",
  "help.document.fai-order.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
