  "help.document.fai-order.views.label": "5.2 表头视图与明细视图",
  "help.document.fai-order.views.orderB1": "可展开行查看行项目摘要（若启用展开）。",
  "help.document.fai-order.views.orderB2": "支持多选批量操作与工具栏下推（选中单条时）。",
  "help.document.fai-order.views.orderB3": "生命周期、执行进度在单据级展示。",
  "help.document.fai-order.views.orderP1": "一行一张首件检验，适合批量审核、下推、关单与跟单。",
  "help.document.fai-order.views.orderTitle": "表头视图（默认）",
  "help.document.fai-order.views.p1": "两种视图服务不同工作场景，可随时切换对比。",
  "help.document.fai-order.views.title": "5.2 表头视图与明细视图",
  "help.document.fai-order.workflow.label": "2. 典型业务流程",
  "help.document.fai-order.workflow.p1": "以下为常见路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.fai-order.workflow.s1": "新建首件检验：空白新建或从上游单据取单带入头行。",
  "help.document.fai-order.workflow.s2": "维护行项目：确认物料、数量、仓库等必填项，保存草稿或提交审核。",
  "help.document.fai-order.workflow.s3": "审核通过：单据进入执行态，可进行下推或过账类操作（若适用）。",
  "help.document.fai-order.workflow.s4": "执行：按业务流程完成收货、发运、检验或财务处理。",
  "help.document.fai-order.workflow.s5": "异常处理：驳回、撤回或走变更/冲销通道（若组织启用）。",
  "help.document.fai-order.workflow.s6": "关单：业务完成后关单，冻结后续下推。",
  "help.document.fai-order.workflow.title": "2. 典型业务流程",
  "help.document.finished-goods-inspection.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.finished-goods-inspection.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.finished-goods-inspection.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.finished-goods-inspection.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.finished-goods-inspection.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.finished-goods-inspection.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.finished-goods-inspection.batch.label": "5.3 工具栏与批量操作",
  "help.document.finished-goods-inspection.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.finished-goods-inspection.batch.title": "5.3 工具栏与批量操作",
  "help.document.finished-goods-inspection.create.b1": "空白新建：适用于无上游单据的零星成品检验。",
  "help.document.finished-goods-inspection.create.b2": "导入：按模板批量创建，导入前请确认主数据编码已存在。",
  "help.document.finished-goods-inspection.create.b3": "已审核单据修改通常需走变更单或冲销流程，勿直接改已生效数据。",
  "help.document.finished-goods-inspection.create.label": "5.1 新建与取单",
  "help.document.finished-goods-inspection.create.p1": "从生产工单或完工汇报取单。",
  "help.document.finished-goods-inspection.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
  "help.document.finished-goods-inspection.create.s2": "在取单弹窗中筛选来源单据行，确认带入头行信息。",
  "help.document.finished-goods-inspection.create.s3": "在表单中补全仓库、数量、日期等必填项，检查行单位与数量。",
  "help.document.finished-goods-inspection.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.finished-goods-inspection.create.title": "5.1 新建与取单",
  "help.document.finished-goods-inspection.detail.b1": "查看：只读打开详情，可查看关联链路。",
  "help.document.finished-goods-inspection.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.finished-goods-inspection.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.finished-goods-inspection.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.finished-goods-inspection.detail.label": "5.6 详情抽屉与行操作",
  "help.document.finished-goods-inspection.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.finished-goods-inspection.detail.title": "5.6 详情抽屉与行操作",
  "help.document.finished-goods-inspection.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.finished-goods-inspection.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.finished-goods-inspection.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效成品检验。",
  "help.document.finished-goods-inspection.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.finished-goods-inspection.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.finished-goods-inspection.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
  "help.document.finished-goods-inspection.faq.q1": "Q: 为什么下推或审核按钮是灰的？",
  "help.document.finished-goods-inspection.faq.q2": "Q: 表头视图与明细视图数量不一致？",
  "help.document.finished-goods-inspection.faq.q3": "Q: 已审核单据如何修改？",
  "help.document.finished-goods-inspection.faq.q4": "Q: 导入失败常见原因？",
  "help.document.finished-goods-inspection.faq.q5": "Q: 明细视图为什么不能批量操作？",
  "help.document.finished-goods-inspection.faq.q6": "Q: 看不到某工具栏按钮？",
  "help.document.finished-goods-inspection.guide.label": "5. 操作指南",
  "help.document.finished-goods-inspection.layout.b1": "指标卡：待审核、逾期、待执行等；部分卡片可点击自动带入筛选。",
  "help.document.finished-goods-inspection.layout.b2": "工具栏：新建/取单、下推（需选中单条）、批量审核、打印、导入导出等。",
  "help.document.finished-goods-inspection.layout.b3": "列表列：单号叠列伙伴/物料、进度与右侧固定状态；行操作提供查看、编辑、审核等。",
  "help.document.finished-goods-inspection.layout.b4": "交期或到期类高亮以页面实际配置为准。",
  "help.document.finished-goods-inspection.layout.label": "3. 页面布局",
  "help.document.finished-goods-inspection.layout.p1": "页面自上而下分为指标区（若有）、工具栏与列表区；右上角可切换表头/明细/帮助视图。",
  "help.document.finished-goods-inspection.layout.title": "3. 页面布局",
  "help.document.finished-goods-inspection.lifecycle.auditB1": "草稿：可编辑、可删除（有权限时）。",
  "help.document.finished-goods-inspection.lifecycle.auditB2": "待审核：等待审批人处理，通常不可直接下推。",
  "help.document.finished-goods-inspection.lifecycle.auditB3": "已审核：可下推、可打印，修改需走正式变更通道。",
