  "help.document.finished-goods-inspection.lifecycle.auditTitle": "审核相关",
  "help.document.finished-goods-inspection.lifecycle.closeB1": "批量关单前请确认无进行中的下游作业。",
  "help.document.finished-goods-inspection.lifecycle.closeB2": "误关单且业务允许时，可使用批量重开恢复执行态。",
