  "help.document.finished-goods-inspection.lifecycle.title": "5.5 状态与审核",
  "help.document.finished-goods-inspection.overview.b1": "记录成品检验业务数据，作为下游流程的依据。",
  "help.document.finished-goods-inspection.overview.b2": "支持表头/明细视图切换，满足不同岗位核对习惯。",
  "help.document.finished-goods-inspection.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.finished-goods-inspection.overview.b4": "支持从上游业务单据取单，减少重复录入。",
