  "help.document.incoming-inspection.push.b1": "质检放行后允许入库过账。",
  "help.document.incoming-inspection.push.b2": "不合格品走退货或隔离流程。",
  "help.document.incoming-inspection.push.b3": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.incoming-inspection.push.b4": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.incoming-inspection.push.b5": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.incoming-inspection.push.b6": "具体可下推类型以工具栏与行内菜单实际展示为准。",
