  "help.document.internal-audit.overview.b1": "记录内部审核业务数据，作为下游流程的依据。",
  "help.document.internal-audit.overview.b2": "支持表头/明细视图切换，满足不同岗位核对习惯。",
  "help.document.internal-audit.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.internal-audit.overview.b4": "工具栏提供新建、批量与导入导出（以权限为准）。",
