  "help.document.maintenance-items.lifecycle.auditB2": "待处理：等待相关人员处理。",
  "help.document.maintenance-items.lifecycle.auditB3": "已完成：只读或有限编辑，依单据类型而定。",
  "help.document.maintenance-items.lifecycle.auditP1": "是否启用多级审核由组织配置决定；行内按钮可能显示提交、通过、驳回、撤回等。",
  "help.document.maintenance-items.lifecycle.auditTitle": "审核相关",
  "help.document.maintenance-items.lifecycle.closeB1": "批量关单前请确认无进行中的下游作业。",
  "help.document.maintenance-items.lifecycle.closeB2": "误关单且业务允许时，可使用批量重开恢复执行态。",
  "help.document.maintenance-items.lifecycle.closeP1": "关单表示业务终止或已全部执行完毕，关单后通常不可再下推。",
  "help.document.maintenance-items.lifecycle.closeTitle": "关单与重开",
  "help.document.maintenance-items.lifecycle.label": "5.5 状态与审核",
