  "help.document.maintenance-plan-calendar.create.label": "5.1 新建与取单",
  "help.document.maintenance-plan-calendar.create.p1": "日历数据来自保养计划与执行单，本页通常不提供新建入口。",
  "help.document.maintenance-plan-calendar.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
