  "help.document.maintenance-plan-calendar.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.maintenance-plan-calendar.create.title": "5.1 新建与取单",
  "help.document.maintenance-plan-calendar.detail.b1": "查看：只读打开详情，可查看关联链路。",
  "help.document.maintenance-plan-calendar.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.maintenance-plan-calendar.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.maintenance-plan-calendar.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.maintenance-plan-calendar.detail.label": "5.6 详情抽屉与行操作",
  "help.document.maintenance-plan-calendar.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.maintenance-plan-calendar.detail.title": "5.6 详情抽屉与行操作",
  "help.document.maintenance-plan-calendar.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.maintenance-plan-calendar.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.maintenance-plan-calendar.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效保养计划日历。",
  "help.document.maintenance-plan-calendar.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.maintenance-plan-calendar.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.maintenance-plan-calendar.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
  "help.document.maintenance-plan-calendar.faq.q1": "Q: 为什么下推或审核按钮是灰的？",
