  "help.document.maintenance-plans.lifecycle.title": "5.5 状态与审核",
  "help.document.maintenance-plans.overview.b1": "记录保养计划业务数据，作为下游流程的依据。",
  "help.document.maintenance-plans.overview.b2": "关联设备台账，执行记录回写设备状态与履历。",
  "help.document.maintenance-plans.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.maintenance-plans.overview.b4": "工具栏提供新建、批量与导入导出（以权限为准）。",
  "help.document.maintenance-plans.overview.label": "1. 概述",
  "help.document.maintenance-plans.overview.p1": "保养计划按周期生成保养任务，可下推保养执行单。",
  "help.document.maintenance-plans.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.maintenance-plans.overview.title": "1. 概述",
  "help.document.maintenance-plans.push.alert": "下推按钮置灰时，将鼠标悬停可查看具体原因（未审核、模块未启用、无权限、无可推数量等）。",
  "help.document.maintenance-plans.push.b1": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.maintenance-plans.push.b2": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.maintenance-plans.push.b3": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.maintenance-plans.push.b4": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.maintenance-plans.push.b5": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.maintenance-plans.push.b6": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.maintenance-plans.push.b7": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.maintenance-plans.push.b8": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.maintenance-plans.push.label": "5.4 下推与下游单据",
  "help.document.maintenance-plans.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.maintenance-plans.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.maintenance-plans.push.title": "5.4 下推与下游单据",
  "help.document.maintenance-plans.search.b1": "关键词：模糊匹配单号、编码、名称等主字段。",
  "help.document.maintenance-plans.search.b2": "伙伴/仓库/部门：按业务维度下拉筛选（若已配置）。",
  "help.document.maintenance-plans.search.b3": "业务日期范围：按单据日期或计划日期过滤。",
  "help.document.maintenance-plans.search.b4": "生命周期/状态：筛选草稿、待审核、执行中、已关单等。",
  "help.document.maintenance-plans.search.b5": "高级搜索：展开更多条件（含自定义字段，若已配置）。",
