  "help.document.mold-maintenance-schemes.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.mold-maintenance-schemes.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
