  "help.document.mold-returns.overview.title": "1. 概述",
  "help.document.mold-returns.push.alert": "下推按钮置灰时，将鼠标悬停可查看具体原因（未审核、模块未启用、无权限、无可推数量等）。",
  "help.document.mold-returns.push.b1": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.mold-returns.push.b2": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.mold-returns.push.b3": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.mold-returns.push.b4": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.mold-returns.push.b5": "具体可下推类型以工具栏与行内菜单实际展示为准。",
