  "help.document.packing-binding.workflow.s1": "新建装箱绑定：空白新建或从上游单据取单带入头行。",
  "help.document.packing-binding.workflow.s2": "维护行项目：确认物料、数量、仓库等必填项，保存草稿或提交审核。",
  "help.document.packing-binding.workflow.s3": "审核通过：单据进入执行态，可进行下推或过账类操作（若适用）。",
  "help.document.packing-binding.workflow.s4": "执行：按业务流程完成收货、发运、检验或财务处理。",
  "help.document.packing-binding.workflow.s5": "异常处理：驳回、撤回或走变更/冲销通道（若组织启用）。",
  "help.document.packing-binding.workflow.s6": "关单：业务完成后关单，冻结后续下推。",
  "help.document.packing-binding.workflow.title": "2. 典型业务流程",
  "help.document.patrol-routes.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.patrol-routes.batch.b2": "批量操作：以工具栏实际按钮为准，置灰时请悬停查看原因。",
  "help.document.patrol-routes.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.patrol-routes.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.patrol-routes.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.patrol-routes.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.patrol-routes.batch.label": "5.3 工具栏与批量操作",
  "help.document.patrol-routes.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.patrol-routes.batch.title": "5.3 工具栏与批量操作",
  "help.document.patrol-routes.create.b1": "空白新建：适用于无上游单据的零星巡检路线。",
  "help.document.patrol-routes.create.b2": "导入：按模板批量创建，导入前请确认主数据编码已存在。",
  "help.document.patrol-routes.create.b3": "已审核单据修改通常需走变更单或冲销流程，勿直接改已生效数据。",
  "help.document.patrol-routes.create.label": "5.1 新建与取单",
  "help.document.patrol-routes.create.p1": "推荐优先使用取单或复制类似巡检路线，保证与上游数据一致。",
  "help.document.patrol-routes.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
  "help.document.patrol-routes.create.s2": "在取单弹窗中筛选来源单据行，确认带入头行信息。",
  "help.document.patrol-routes.create.s3": "在表单中补全仓库、数量、日期等必填项，检查行单位与数量。",
  "help.document.patrol-routes.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.patrol-routes.create.title": "5.1 新建与取单",
  "help.document.patrol-routes.detail.b1": "查看：只读打开详情，可查看关联链路。",
  "help.document.patrol-routes.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.patrol-routes.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.patrol-routes.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.patrol-routes.detail.label": "5.6 详情抽屉与行操作",
  "help.document.patrol-routes.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.patrol-routes.detail.title": "5.6 详情抽屉与行操作",
  "help.document.patrol-routes.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.patrol-routes.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.patrol-routes.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效巡检路线。",
  "help.document.patrol-routes.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.patrol-routes.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.patrol-routes.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
  "help.document.patrol-routes.faq.q1": "Q: 为什么下推或审核按钮是灰的？",
  "help.document.patrol-routes.faq.q2": "Q: 表头视图与明细视图数量不一致？",
  "help.document.patrol-routes.faq.q3": "Q: 已审核单据如何修改？",
  "help.document.patrol-routes.faq.q4": "Q: 导入失败常见原因？",
  "help.document.patrol-routes.faq.q5": "Q: 明细视图为什么不能批量操作？",
  "help.document.patrol-routes.faq.q6": "Q: 看不到某工具栏按钮？",
  "help.document.patrol-routes.guide.label": "5. 操作指南",
  "help.document.patrol-routes.layout.b1": "指标卡：待处理、逾期等快照（若有）。",
  "help.document.patrol-routes.layout.b2": "工具栏：新建/取单、下推（需选中单条）、批量审核、打印、导入导出等。",
  "help.document.patrol-routes.layout.b3": "列表列：单号叠列伙伴/物料、进度与右侧固定状态；行操作提供查看、编辑、审核等。",
  "help.document.patrol-routes.layout.b4": "交期或到期类高亮以页面实际配置为准。",
  "help.document.patrol-routes.layout.label": "3. 页面布局",
  "help.document.patrol-routes.layout.p1": "页面自上而下分为指标区（若有）、工具栏与列表区；右上角可切换表头/明细/帮助视图。",
  "help.document.patrol-routes.layout.title": "3. 页面布局",
  "help.document.patrol-routes.lifecycle.auditB1": "草稿：可编辑、可删除（有权限时）。",
  "help.document.patrol-routes.lifecycle.auditB2": "待处理：等待相关人员处理。",
  "help.document.patrol-routes.lifecycle.auditB3": "已完成：只读或有限编辑，依单据类型而定。",
  "help.document.patrol-routes.lifecycle.auditP1": "是否启用多级审核由组织配置决定；行内按钮可能显示提交、通过、驳回、撤回等。",
  "help.document.patrol-routes.lifecycle.auditTitle": "审核相关",
  "help.document.patrol-routes.lifecycle.closeB1": "批量关单前请确认无进行中的下游作业。",
  "help.document.patrol-routes.lifecycle.closeB2": "误关单且业务允许时，可使用批量重开恢复执行态。",
  "help.document.patrol-routes.lifecycle.closeP1": "关单表示业务终止或已全部执行完毕，关单后通常不可再下推。",
  "help.document.patrol-routes.lifecycle.closeTitle": "关单与重开",
  "help.document.patrol-routes.lifecycle.label": "5.5 状态与审核",
  "help.document.patrol-routes.lifecycle.p1": "右侧「生命周期」或状态列展示当前阶段，与行内审核按钮联动。",
  "help.document.patrol-routes.lifecycle.title": "5.5 状态与审核",
  "help.document.patrol-routes.overview.b1": "记录巡检路线业务数据，作为下游流程的依据。",
  "help.document.patrol-routes.overview.b2": "关联设备台账，执行记录回写设备状态与履历。",
  "help.document.patrol-routes.overview.b3": "配合指标卡与状态列快速发现待处理与异常单据。",
  "help.document.patrol-routes.overview.b4": "工具栏提供新建、批量与导入导出（以权限为准）。",
