  "help.document.patrol-routes.push.label": "5.4 下推与下游单据",
  "help.document.patrol-routes.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.patrol-routes.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.patrol-routes.push.title": "5.4 下推与下游单据",
  "help.document.patrol-routes.search.b1": "关键词：模糊匹配单号、编码、名称等主字段。",
  "help.document.patrol-routes.search.b2": "伙伴/仓库/部门：按业务维度下拉筛选（若已配置）。",
  "help.document.patrol-routes.search.b3": "业务日期范围：按单据日期或计划日期过滤。",
  "help.document.patrol-routes.search.b4": "生命周期/状态：筛选草稿、待审核、执行中、已关单等。",
  "help.document.patrol-routes.search.b5": "高级搜索：展开更多条件（含自定义字段，若已配置）。",
