  "help.document.purchase-inquiry.faq.q4": "Q: 多家供应商报价如何录入？",
  "help.document.purchase-inquiry.faq.q5": "Q: 明细视图能下推吗？",
  "help.document.purchase-inquiry.faq.q6": "Q: 未定标能否下推？",
  "help.document.purchase-inquiry.guide.label": "5. 操作指南",
  "help.document.purchase-inquiry.layout.b1": "工具栏左侧：新建/取单、下推采购订单（需选中单条询价）；右侧：批量删除、批量审核、导入导出等。",
  "help.document.purchase-inquiry.layout.b2": "行操作含查看、编辑、报价、比价定标、审核、打印等。",
  "help.document.purchase-inquiry.layout.b3": "列表展示报价截止日、下推进度、审核信息与右侧固定生命周期状态。",
  "help.document.purchase-inquiry.layout.b4": "详情抽屉集中展示供应商报价与定标结果摘要。",
  "help.document.purchase-inquiry.layout.label": "3. 页面布局",
  "help.document.purchase-inquiry.layout.p1": "页面自上而下分为工具栏与列表区；右上角可切换表头/明细/帮助视图。",
  "help.document.purchase-inquiry.layout.title": "3. 页面布局",
  "help.document.purchase-inquiry.lifecycle.auditB1": "草稿：可编辑、可删除（有权限时），可维护供应商与报价。",
