  "help.document.purchase-order.create.s1": "点击新建旁下拉，选择「从采购申请取单」或「从采购询价取单」。",
  "help.document.purchase-order.create.s2": "在取单弹窗中筛选并勾选来源单据行，确认带入头行。",
  "help.document.purchase-order.create.s3": "在表单中补全交期、价格类型、收货仓库等必填项，检查行数量与单位。",
  "help.document.purchase-order.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.purchase-order.create.title": "5.1 新建与取单",
  "help.document.purchase-order.detail.b1": "查看：只读打开详情，可复制单号、查看下推链路。",
  "help.document.purchase-order.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.purchase-order.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.purchase-order.detail.b4": "抽屉内可刷新单据，审核或下推成功后列表与抽屉数据会同步更新。",
  "help.document.purchase-order.detail.label": "5.6 详情抽屉与行操作",
  "help.document.purchase-order.detail.p1": "点击行内「查看」或单号区域打开详情抽屉，集中阅读头信息、行项目、变更记录与跟踪信息。",
  "help.document.purchase-order.detail.title": "5.6 详情抽屉与行操作",
  "help.document.purchase-order.faq.a1": "A: 常见原因：未选中订单、选中多条、订单未审核、目标模块未启用、无下推权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.purchase-order.faq.a2": "A: 收货通知用于提前通知仓库预计到货，便于安排收货；采购收货/入库是实际入库过账。组织可按流程先通知再入库，或在 capability 允许时直接入库。",
  "help.document.purchase-order.faq.a3": "A: 开启工具栏「交期逾期高亮」后，系统按行交期与到货进度标记尚未完成且已过交期的订单或行。",
  "help.document.purchase-order.faq.a4": "A: 请使用「采购订单变更」下推生成变更单，不要直接编辑已审核订单。",
  "help.document.purchase-order.faq.a5": "A: 明细视图按行展示且为只读，无行勾选；批量审核、下推、关单等请在表头视图进行。",
  "help.document.purchase-order.faq.a6": "A: 供应商/物料编码不存在、单位不匹配、必填日期为空、价格类型不合法等。请先维护主数据，并下载最新导入模板对照字段说明。",
