  "help.document.purchase-requisition.faq.a1": "A: 候选行可能已被其他申请引用、数量为 0 或物料不可采购；请查看取单弹窗中的「不可创建」标记与原因。",
  "help.document.purchase-requisition.faq.a2": "A: 采购订单必须关联供应商；下推预览会要求选择或确认供应商，也可使用行上建议供应商。",
  "help.document.purchase-requisition.faq.a3": "A: 申请是内部请购单据；询价是对外询价。可先下推询价比价，再转采购订单。",
  "help.document.purchase-requisition.faq.a4": "A: 需求计算结果可能缺少需求日期，系统要求确认或批量填写后才能生成申请。",
