  "help.document.purchase-requisition.overview.label": "1. 概述",
  "help.document.purchase-requisition.overview.p1": "采购申请用于提出物料采购需求，记录请购数量、需求日期与建议供应商。可从需求计算取单生成，审核后可下推采购订单或采购询价。",
  "help.document.purchase-requisition.overview.p2": "本页面向计划员与采购员：既要在表头视图批量下推，也要在明细视图按物料核对未转采购数量。",
  "help.document.purchase-requisition.overview.title": "1. 概述",
  "help.document.purchase-requisition.push.alert": "从需求计算取单与下推采购是两条路径：前者创建申请，后者在申请审核后转采购订单或询价。",
  "help.document.purchase-requisition.push.b1": "采购订单：按供应商与行数量生成采购订单，带入请购物料与交期。",
  "help.document.purchase-requisition.push.b2": "采购询价：生成询价单，便于比价后再转采购订单。",
  "help.document.purchase-requisition.push.b3": "预览窗展示每行可推数量与 blocking 原因。",
  "help.document.purchase-requisition.push.b4": "下推采购订单前请确认供应商主数据已维护且启用。",
  "help.document.purchase-requisition.push.b5": "部分行已转采购后，可推数量会扣减已下推部分。",
  "help.document.purchase-requisition.push.b6": "询价下推可选行，适合多家询价比价场景。",
  "help.document.purchase-requisition.push.b7": "下推成功后可在列表下推进度或详情中查看下游单号。",
  "help.document.purchase-requisition.push.b8": "置灰时悬停查看原因（未审核、无权限、无可推数量等）。",
  "help.document.purchase-requisition.push.label": "5.4 下推与下游单据",
  "help.document.purchase-requisition.push.p1": "下推入口位于工具栏「下推」按钮（需选中恰好一条申请）或行内下推菜单。",
  "help.document.purchase-requisition.push.p2": "下推采购订单时会打开预览窗，需选择供应商并确认可推行。",
  "help.document.purchase-requisition.push.title": "5.4 下推与下游单据",
  "help.document.purchase-requisition.search.b1": "关键词：模糊匹配单号、物料编码或名称。",
  "help.document.purchase-requisition.search.b2": "申请日期范围：按业务日期过滤。",
