  "help.document.purchase-requisition.workflow.p1": "以下为常见请购到采购路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.purchase-requisition.workflow.s1": "创建申请：空白新建，或从需求计算取单带入物料与数量。",
