  "help.document.receipt-notice.detail.p1": "点击行内「查看」打开详情抽屉，阅读头信息、行项目与关联入库单。",
  "help.document.receipt-notice.detail.title": "5.6 详情抽屉与行操作",
  "help.document.receipt-notice.faq.a1": "A: 常见原因：通知未审核、未选中或选中多条、无下推权限、行已无可收数量。请悬停按钮查看具体原因。",
  "help.document.receipt-notice.faq.a2": "A: 通知从采购订单取单，把预计到货信息发给仓库；实际入库通过下推采购收货完成。",
  "help.document.receipt-notice.faq.a3": "A: 若组织允许，采购订单可直接下推采购收货；收货通知用于提前通知仓库的标准流程。",
  "help.document.receipt-notice.faq.a4": "A: 关单通常表示不再收货；请先确认业务上是否放弃剩余数量，并检查组织关单规则。",
  "help.document.receipt-notice.faq.a5": "A: 行可能已无可收数量或采购订单未审核；请查看取单弹窗提示。",
  "help.document.receipt-notice.faq.a6": "A: 不能；请在表头视图选中整张通知后下推。",
