  "help.document.receipt-notice.lifecycle.label": "5.5 状态与审核",
  "help.document.receipt-notice.lifecycle.p1": "右侧状态列展示通知当前阶段，与行内审核按钮联动。",
  "help.document.receipt-notice.lifecycle.title": "5.5 状态与审核",
  "help.document.receipt-notice.overview.b1": "把采购订单的到货计划传递给仓库提前准备。",
  "help.document.receipt-notice.overview.b2": "列表展示入库下推进度，便于跟踪是否已采购收货。",
  "help.document.receipt-notice.overview.b3": "支持从采购订单取单，自动带入供应商、物料与可收数量。",
  "help.document.receipt-notice.overview.b4": "可与采购订单、采购入库形成收货链路。",
  "help.document.receipt-notice.overview.label": "1. 概述",
  "help.document.receipt-notice.overview.p1": "收货通知用于通知仓库预计到货信息，记录待收物料、数量与收货仓库。通常从采购订单取单生成，审核后可下推采购收货入库。",
  "help.document.receipt-notice.overview.p2": "本页面向采购员与仓储收货人员：既要在表头视图处理通知单，也要在明细视图按行核对待收数量与入库进度。",
  "help.document.receipt-notice.overview.title": "1. 概述",
  "help.document.receipt-notice.push.alert": "收货通知是采购订单与仓储入库之间的桥梁；未审核通知通常不可下推入库。",
  "help.document.receipt-notice.push.b1": "下推前请确认通知已审核且行上有可收数量。",
  "help.document.receipt-notice.push.b2": "入库下推进度反映已入库数量占通知数量的比例。",
  "help.document.receipt-notice.push.b3": "已完全入库的通知不可重复下推同一数量。",
  "help.document.receipt-notice.push.b4": "下推时系统会校验仓库、批次与质检要求（若启用）。",
  "help.document.receipt-notice.push.b5": "详情抽屉可查看完整下推链路与关联入库单号。",
  "help.document.receipt-notice.push.b6": "置灰时悬停查看原因（未审核、无权限、无可推数量等）。",
  "help.document.receipt-notice.push.b7": "也可在仓储模块从通知拉式创建入库（若组织启用）。",
  "help.document.receipt-notice.push.b8": "收货数量受来源采购订单剩余可收数量约束。",
  "help.document.receipt-notice.push.label": "5.4 下推采购收货入库",
  "help.document.receipt-notice.push.p1": "下推入口位于工具栏「下推」按钮（需选中恰好一条已审核通知）或行内下推菜单。",
  "help.document.receipt-notice.push.p2": "下推会生成采购收货/入库单，完成实际入库过账。",
  "help.document.receipt-notice.push.title": "5.4 下推采购收货入库",
  "help.document.receipt-notice.search.b1": "关键词：模糊匹配通知单号、供应商或采购订单号。",
  "help.document.receipt-notice.search.b2": "通知日期范围：按业务日期过滤。",
  "help.document.receipt-notice.search.b3": "状态：筛选草稿、待审核、已审核、已关单等。",
  "help.document.receipt-notice.search.b4": "收货仓库：按仓库维度过滤（若搜索栏已配置）。",
  "help.document.receipt-notice.search.b5": "取单弹窗内可切换「仅可转」范围。",
  "help.document.receipt-notice.search.b6": "明细视图可按物料编码快速核对行。",
  "help.document.receipt-notice.search.label": "4. 查询与筛选",
  "help.document.receipt-notice.search.p1": "表头视图与明细视图共用同一套筛选条件。",
  "help.document.receipt-notice.search.title": "4. 查询与筛选",
  "help.document.receipt-notice.views.detailB1": "只读查看，不可在此视图直接编辑行。",
  "help.document.receipt-notice.views.detailB2": "无行勾选，下推入库请切回表头视图。",
  "help.document.receipt-notice.views.detailB3": "可看到行级入库进度。",
  "help.document.receipt-notice.views.detailP1": "一行一条通知行，适合仓储按物料核对待收与入库进度。",
