  "help.document.receipt-notice.views.orderB1": "可展开行查看行项目摘要。",
  "help.document.receipt-notice.views.orderB2": "支持多选批量操作；下推入库需选中单条。",
  "help.document.receipt-notice.views.orderB3": "入库下推进度在通知单级展示。",
  "help.document.receipt-notice.views.orderP1": "一行一张收货通知，适合批量审核与下推入库。",
  "help.document.receipt-notice.views.orderTitle": "表头视图（默认）",
