  "help.document.receipt-notice.views.title": "5.2 表头视图与明细视图",
  "help.document.receipt-notice.workflow.label": "2. 典型业务流程",
  "help.document.receipt-notice.workflow.p1": "以下为常见采购收货路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.receipt-notice.workflow.s1": "创建通知：空白新建，或从采购订单取单勾选可收运行。",
  "help.document.receipt-notice.workflow.s2": "维护头行：确认收货仓库、预计到货日期与行数量，保存或提交审核。",
  "help.document.receipt-notice.workflow.s3": "审核通过：通知进入执行态，仓库可按单准备收货。",
  "help.document.receipt-notice.workflow.s4": "下推入库：选中已审核通知，下推采购收货/入库完成过账。",
  "help.document.receipt-notice.workflow.s5": "进度跟踪：列表入库进度列展示是否已转采购入库。",
  "help.document.receipt-notice.workflow.s6": "关单：全部收货或业务终止后关单。",
  "help.document.receipt-notice.workflow.title": "2. 典型业务流程",
  "help.document.receipt.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.receipt.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.receipt.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.receipt.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.receipt.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.receipt.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.receipt.batch.label": "5.3 工具栏与批量操作",
  "help.document.receipt.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.receipt.batch.title": "5.3 工具栏与批量操作",
  "help.document.receipt.create.b1": "空白新建：适用于无上游单据的零星收款单。",
  "help.document.receipt.create.b2": "导入：按模板批量创建，导入前请确认主数据编码已存在。",
  "help.document.receipt.create.b3": "已审核单据修改通常需走变更单或冲销流程，勿直接改已生效数据。",
  "help.document.receipt.create.label": "5.1 新建与取单",
  "help.document.receipt.create.p1": "从应收单或销售发票取单带入待核销行。",
  "help.document.receipt.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
  "help.document.receipt.create.s2": "在取单弹窗中筛选来源单据行，确认带入头行信息。",
  "help.document.receipt.create.s3": "在表单中补全仓库、数量、日期等必填项，检查行单位与数量。",
  "help.document.receipt.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.receipt.create.title": "5.1 新建与取单",
  "help.document.receipt.detail.b1": "查看：只读打开详情，可查看关联链路。",
  "help.document.receipt.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.receipt.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.receipt.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.receipt.detail.label": "5.6 详情抽屉与行操作",
  "help.document.receipt.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.receipt.detail.title": "5.6 详情抽屉与行操作",
  "help.document.receipt.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.receipt.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.receipt.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效收款单。",
  "help.document.receipt.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.receipt.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.receipt.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
