  "help.document.receivable.push.b1": "下推收款单。",
  "help.document.receivable.push.b2": "账龄分析报表钻取（菜单入口）。",
  "help.document.receivable.push.b3": "下推前请确认单据已审核、目标模块已启用且您具备对应权限。",
  "help.document.receivable.push.b4": "已存在下游单据时，可推数量会扣减已执行部分。",
  "help.document.receivable.push.b5": "部分下推仅在 capability 允许时出现，置灰时悬停查看原因。",
  "help.document.receivable.push.b6": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.receivable.push.b7": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.receivable.push.b8": "具体可下推类型以工具栏与行内菜单实际展示为准。",
  "help.document.receivable.push.label": "5.4 下推与下游单据",
  "help.document.receivable.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.receivable.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.receivable.push.title": "5.4 下推与下游单据",
