  "help.document.sales-contract.create.title": "5.1 新建与取单",
  "help.document.sales-contract.detail.b1": "查看：只读打开详情，可复制合同号、查看下推链路。",
  "help.document.sales-contract.detail.b2": "编辑：草稿状态下打开表单弹窗。",
  "help.document.sales-contract.detail.b3": "审核/打印/下推：与工具栏能力互补。",
