  "help.document.sales-contract.detail.p1": "点击行内「查看」打开详情抽屉，阅读头信息、行项目与下推跟踪。",
  "help.document.sales-contract.detail.title": "5.6 详情抽屉与行操作",
  "help.document.sales-contract.faq.a1": "A: 常见原因：合同未审核、未选中或选中多条、无下推权限、行已无剩余可释放数量。请悬停按钮查看具体原因。",
  "help.document.sales-contract.faq.a2": "A: 需要走销售发运流程选销售订单；直接安排制造选生产工单。同一合同行通常只应通过一种方式释放，请按业务规则操作。",
  "help.document.sales-contract.faq.a3": "A: 预览窗会显示行剩余可释放量；填写值不可超过该上限，可分批多次下推。",
  "help.document.sales-contract.faq.a4": "A: 点击新建旁「从报价单取单」，选择允许转合同的报价；报价 capability 不允许时会提示原因。",
  "help.document.sales-contract.faq.a5": "A: 合同是框架与总量控制；销售订单是具体一次发货/执行单据。合同通过下推分批生成订单。",
  "help.document.sales-contract.faq.a6": "A: 不能；请在表头视图选中整张合同后下推，并在预览窗勾选行与数量。",
