  "help.document.sales-contract.overview.b1": "固化对客户的价格与数量框架，作为分批下单依据。",
  "help.document.sales-contract.overview.b2": "通过下推销售订单或工单释放合同数量。",
  "help.document.sales-contract.overview.b3": "列表展示下推进度，便于跟踪合同执行情况。",
  "help.document.sales-contract.overview.b4": "支持从报价单取单，减少重复录入。",
  "help.document.sales-contract.overview.label": "1. 概述",
  "help.document.sales-contract.overview.p1": "销售合同用于记录与客户的中长期销售框架，包含物料、价格条款与合同数量。可从报价单取单生成，审核后可下推销售订单或生产工单。",
  "help.document.sales-contract.overview.p2": "本页面向销售经理与计划人员：既要在表头视图管理合同生命周期，也要在明细视图按行核对已释放数量与下推进度。",
  "help.document.sales-contract.overview.title": "1. 概述",
  "help.document.sales-contract.push.alert": "合同下推是释放数量的正式通道；释放数量累计不可超过合同行总量。",
  "help.document.sales-contract.push.b1": "销售订单：按释放数量生成销售订单，扣减合同剩余可释放量。",
  "help.document.sales-contract.push.b2": "生产工单：对制造类行直接生成工单，可选择草稿或确认下达模式。",
  "help.document.sales-contract.push.b3": "预览窗会校验释放数量不超过行剩余可释放量。",
  "help.document.sales-contract.push.b4": "blocking 行需先处理（如合同未审核、物料停用等）。",
  "help.document.sales-contract.push.b5": "下推成功后列表下推进度会更新。",
  "help.document.sales-contract.push.b6": "销售订单页也支持从销售合同取单，与合同页下推互为补充。",
  "help.document.sales-contract.push.b7": "工单下推模式「确认」会直接下达，「草稿」仅生成草稿工单。",
  "help.document.sales-contract.push.b8": "置灰时悬停查看原因（未审核、无权限、无可释放数量等）。",
  "help.document.sales-contract.push.label": "5.4 下推与下游单据",
  "help.document.sales-contract.push.p1": "下推入口位于工具栏「下推」按钮（需选中恰好一条合同）或行内下推菜单。",
  "help.document.sales-contract.push.p2": "下推前会打开预览窗，勾选可释放行并填写释放数量。",
  "help.document.sales-contract.push.title": "5.4 下推与下游单据",
  "help.document.sales-contract.search.b1": "关键词：模糊匹配合同号、客户名称等。",
  "help.document.sales-contract.search.b2": "单号、客户、销售人员：精确或下拉检索。",
  "help.document.sales-contract.search.b3": "合同日期范围：按业务日期过滤。",
  "help.document.sales-contract.search.b4": "状态：筛选草稿、待审核、执行中、已关单等。",
  "help.document.sales-contract.search.b5": "高级搜索：展开更多条件（若已配置）。",
  "help.document.sales-contract.search.b6": "明细视图可按物料核对行级释放进度。",
