  "help.document.sales-contract.views.label": "5.2 表头视图与明细视图",
  "help.document.sales-contract.views.orderB1": "可展开行查看行项目摘要。",
  "help.document.sales-contract.views.orderB2": "支持多选批量操作；下推需选中单条。",
  "help.document.sales-contract.views.orderB3": "下推进度与剩余数量在合同级展示。",
  "help.document.sales-contract.views.orderP1": "一行一张销售合同，适合批量审核与下推。",
