  "help.document.sales-contract.workflow.label": "2. 典型业务流程",
  "help.document.sales-contract.workflow.p1": "以下为常见合同到执行路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.sales-contract.workflow.s1": "创建合同：空白新建，或从报价单取单带入头行。",
  "help.document.sales-contract.workflow.s2": "维护条款：确认客户、合同有效期、行项目数量与价格类型，提交审核。",
  "help.document.sales-contract.workflow.s3": "审核通过：合同进入执行态，可按行释放数量。",
  "help.document.sales-contract.workflow.s4": "下推销售订单：按行选择释放数量生成销售订单。",
  "help.document.sales-contract.workflow.s5": "或下推生产工单：对制造类合同行直接释放工单（可选草稿或确认下达模式）。",
  "help.document.sales-contract.workflow.s6": "关单：全部释放或业务终止后关单。",
  "help.document.sales-contract.workflow.title": "2. 典型业务流程",
  "help.document.sales-delivery.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.sales-delivery.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.sales-delivery.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.sales-delivery.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.sales-delivery.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.sales-delivery.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.sales-delivery.batch.label": "5.3 工具栏与批量操作",
  "help.document.sales-delivery.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
