  "help.document.sales-delivery.detail.title": "5.6 详情抽屉与行操作",
  "help.document.sales-delivery.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
