  "help.document.sales-delivery.views.title": "5.2 表头视图与明细视图",
  "help.document.sales-delivery.workflow.label": "2. 典型业务流程",
  "help.document.sales-delivery.workflow.p1": "以下为常见路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.sales-delivery.workflow.s1": "新建销售出库：空白新建或从上游单据取单带入头行。",
  "help.document.sales-delivery.workflow.s2": "维护行项目：确认物料、数量、仓库等必填项，保存草稿或提交审核。",
  "help.document.sales-delivery.workflow.s3": "审核通过：单据进入执行态，可进行下推或过账类操作（若适用）。",
  "help.document.sales-delivery.workflow.s4": "执行：按业务流程完成收货、发运、检验或财务处理。",
  "help.document.sales-delivery.workflow.s5": "异常处理：驳回、撤回或走变更/冲销通道（若组织启用）。",
  "help.document.sales-delivery.workflow.s6": "关单：业务完成后关单，冻结后续下推。",
  "help.document.sales-delivery.workflow.title": "2. 典型业务流程",
  "help.document.sales-forecast.batch.b1": "批量删除：仅允许删除草稿等未执行预测。",
  "help.document.sales-forecast.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.sales-forecast.batch.b3": "批量关单：终止或完结，关单前请确认无未完成下推。",
  "help.document.sales-forecast.batch.b4": "批量打印：选中单条后打印模板单据。",
  "help.document.sales-forecast.batch.b5": "导出：导出当前列表筛选结果。",
  "help.document.sales-forecast.batch.b6": "下推需求计算请在选中单条已审核预测后使用工具栏下推按钮。",
  "help.document.sales-forecast.batch.label": "5.3 工具栏与批量操作",
  "help.document.sales-forecast.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.sales-forecast.batch.title": "5.3 工具栏与批量操作",
