  "help.document.sales-forecast.create.b2": "产品范围切换：物料选择可限定自制件或全部物料（以表单配置为准）。",
  "help.document.sales-forecast.create.b3": "已审核预测通过下推修改计划输入，不要直接改已下推行数量（除非组织允许反审）。",
  "help.document.sales-forecast.create.label": "5.1 新建与编辑",
