  "help.document.sales-forecast.create.s1": "点击「新建」进入表单页，填写预测名称、期间与备注。",
  "help.document.sales-forecast.create.s2": "添加行项目：选择物料、预测数量、单位与需求日期；可使用物料批量选择器。",
