  "help.document.sales-forecast.workflow.p1": "以下为常见预测到计划路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.sales-forecast.workflow.s1": "创建预测：列表新建进入表单页，或导入批量创建，维护预测期间与行项目数量。",
  "help.document.sales-forecast.workflow.s2": "维护行项目：选择物料、预测数量、单位与需求日期，保存草稿或提交审核。",
  "help.document.sales-forecast.workflow.s3": "审核通过：预测进入可下推状态，下推进度列展示执行情况。",
  "help.document.sales-forecast.workflow.s4": "下推需求计算：选中已审核预测，预览勾选可推行并确认，生成需求运算单。",
