  "help.document.shipment-notice.faq.a1": "A: 行可能已无可发数量、订单未审核或已被其他通知引用；请查看取单弹窗中的不可创建标记。",
  "help.document.shipment-notice.faq.a2": "A: 通知是发运指令，销售出库是实际出库过账；审核后系统会按配置生成或关联销售出库单。",
  "help.document.shipment-notice.faq.a3": "A: 请确认通知已审核，并在仓储模块完成销售出库；同时检查库存与权限。",
  "help.document.shipment-notice.faq.a4": "A: 若组织允许空白新建，可直接创建；常规订单发运仍建议从销售订单取单以保证数量一致。",
  "help.document.shipment-notice.faq.a5": "A: 批量审核请在表头视图进行；明细视图为只读行级查看。",
