  "help.document.shipment-notice.lifecycle.title": "5.5 状态与审核",
  "help.document.shipment-notice.overview.b1": "把销售订单的发运需求传递给仓库执行。",
  "help.document.shipment-notice.overview.b2": "列表展示出库下推进度，便于跟踪是否已生成销售出库。",
  "help.document.shipment-notice.overview.b3": "支持从销售订单取单，自动带入客户、物料与可发数量。",
  "help.document.shipment-notice.overview.b4": "可与销售订单、销售出库形成发运链路。",
  "help.document.shipment-notice.overview.label": "1. 概述",
  "help.document.shipment-notice.overview.p1": "发货通知用于通知仓库按销售订单备货发运，记录待发物料、数量与出库仓库。通常从销售订单取单生成，审核后可驱动下游销售出库。",
  "help.document.shipment-notice.overview.p2": "本页面向销售内勤与仓储发货人员：既要在表头视图处理通知单，也要在明细视图按行核对待发数量与出库进度。",
  "help.document.shipment-notice.overview.title": "1. 概述",
  "help.document.shipment-notice.push.alert": "发货通知页工具栏通常不提供独立「下推」菜单；请关注出库进度列并在仓储销售出库模块完成过账。",
  "help.document.shipment-notice.push.b1": "已关联销售出库单的通知，列表会展示出库单号并可跳转跟踪。",
  "help.document.shipment-notice.push.b2": "出库下推进度反映已出库数量占通知数量的比例。",
  "help.document.shipment-notice.push.b3": "未完成出库的通知仍可在仓储侧继续处理。",
  "help.document.shipment-notice.push.b4": "发运数量受来源销售订单剩余可发数量约束。",
  "help.document.shipment-notice.push.b5": "若出库失败，请检查仓库库存与单据审核状态。",
  "help.document.shipment-notice.push.b6": "详情抽屉可查看完整下推链路与关联单号。",
  "help.document.shipment-notice.push.b7": "部分场景通知审核成功提示中会直接给出销售出库单号。",
  "help.document.shipment-notice.push.b8": "无出库权限的用户仍可创建通知，但无法完成下游出库。",
  "help.document.shipment-notice.push.label": "5.4 下游销售出库",
  "help.document.shipment-notice.push.p1": "发货通知本身以下游「销售出库」为执行终点；列表出库进度列展示是否已生成销售出库单。",
  "help.document.shipment-notice.push.p2": "具体出库生成方式取决于组织配置：可能在通知审核后自动/手动触发出库。",
  "help.document.shipment-notice.push.title": "5.4 下游销售出库",
  "help.document.shipment-notice.search.b1": "关键词：模糊匹配通知单号、客户或销售订单号。",
  "help.document.shipment-notice.search.b2": "通知日期范围：按业务日期过滤。",
  "help.document.shipment-notice.search.b3": "状态：筛选草稿、待审核、已审核、已关单等。",
  "help.document.shipment-notice.search.b4": "出库仓库：按仓库维度过滤（若搜索栏已配置）。",
  "help.document.shipment-notice.search.b5": "取单弹窗内可切换「仅可转」范围。",
  "help.document.shipment-notice.search.b6": "明细视图可按物料编码快速核对行。",
  "help.document.shipment-notice.search.label": "4. 查询与筛选",
  "help.document.shipment-notice.search.p1": "表头视图与明细视图共用同一套筛选条件。",
  "help.document.shipment-notice.search.title": "4. 查询与筛选",
  "help.document.shipment-notice.views.detailB1": "只读查看，不可在此视图直接编辑行。",
  "help.document.shipment-notice.views.detailB2": "无行勾选，批量操作请切回表头视图。",
