  "help.document.spare-part-requisitions.guide.label": "5. 操作指南",
  "help.document.spare-part-requisitions.layout.b1": "指标卡：待审核、逾期、待执行等；部分卡片可点击自动带入筛选。",
  "help.document.spare-part-requisitions.layout.b2": "工具栏：新建/取单、下推（需选中单条）、批量审核、打印、导入导出等。",
