  "help.document.spare-parts.lifecycle.auditB2": "待处理：等待相关人员处理。",
  "help.document.spare-parts.lifecycle.auditB3": "已完成：只读或有限编辑，依单据类型而定。",
  "help.document.spare-parts.lifecycle.auditP1": "是否启用多级审核由组织配置决定；行内按钮可能显示提交、通过、驳回、撤回等。",
  "help.document.spare-parts.lifecycle.auditTitle": "审核相关",
