  "help.document.stocktaking.overview.label": "1. 概述",
  "help.document.stocktaking.overview.p1": "盘点单用于周期或抽盘库存，录入账面与实盘差异并过账调整库存。",
  "help.document.stocktaking.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.stocktaking.overview.title": "1. 概述",
