  "help.document.stocktaking.views.detailB3": "分页按行计数，与表头视图总数可能不同属正常现象。",
  "help.document.stocktaking.views.detailP1": "一行一条行项目，适合按物料核对数量与执行进度。",
  "help.document.stocktaking.views.detailTitle": "明细视图",
  "help.document.stocktaking.views.label": "5.2 表头视图与明细视图",
  "help.document.stocktaking.views.orderB1": "可展开行查看行项目摘要（若启用展开）。",
  "help.document.stocktaking.views.orderB2": "支持多选批量操作与工具栏下推（选中单条时）。",
  "help.document.stocktaking.views.orderB3": "生命周期、执行进度在单据级展示。",
  "help.document.stocktaking.views.orderP1": "一行一张盘点单，适合批量审核、下推、关单与跟单。",
  "help.document.stocktaking.views.orderTitle": "表头视图（默认）",
  "help.document.stocktaking.views.p1": "两种视图服务不同工作场景，可随时切换对比。",
  "help.document.stocktaking.views.title": "5.2 表头视图与明细视图",
  "help.document.stocktaking.workflow.label": "2. 典型业务流程",
  "help.document.stocktaking.workflow.p1": "以下为常见路径，具体节点是否启用取决于组织配置与权限。",
  "help.document.stocktaking.workflow.s1": "新建盘点单：选择仓库、盘点类型与物料范围。",
  "help.document.stocktaking.workflow.s2": "冻结/锁盘：限制出入库（若组织启用）。",
  "help.document.stocktaking.workflow.s3": "录入实盘数量：PC 或移动端录入。",
  "help.document.stocktaking.workflow.s4": "审核差异：确认盘盈盘亏原因。",
  "help.document.stocktaking.workflow.s5": "过账：生成库存调整记录。",
  "help.document.stocktaking.workflow.s6": "关闭盘点单：完成本次盘点周期。",
  "help.document.stocktaking.workflow.title": "2. 典型业务流程",
  "help.document.tool-borrows.batch.b1": "批量删除：通常仅允许删除草稿等未执行单据。",
  "help.document.tool-borrows.batch.b2": "批量审核：提交、撤回、通过、驳回（以组织审核配置为准）。",
  "help.document.tool-borrows.batch.b3": "批量关单/重开：终止或恢复执行（若提供）。",
  "help.document.tool-borrows.batch.b4": "批量下推：选中符合条件的单据批量生成下游（以 capability 为准）。",
  "help.document.tool-borrows.batch.b5": "批量打印：选中单条或多条后打印模板单据。",
  "help.document.tool-borrows.batch.b6": "导出：导出当前列表筛选结果。",
  "help.document.tool-borrows.batch.label": "5.3 工具栏与批量操作",
  "help.document.tool-borrows.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.tool-borrows.batch.title": "5.3 工具栏与批量操作",
  "help.document.tool-borrows.create.b1": "空白新建：适用于无上游单据的零星工装借用。",
  "help.document.tool-borrows.create.b2": "导入：按模板批量创建，导入前请确认主数据编码已存在。",
  "help.document.tool-borrows.create.b3": "已审核单据修改通常需走变更单或冲销流程，勿直接改已生效数据。",
  "help.document.tool-borrows.create.label": "5.1 新建与取单",
  "help.document.tool-borrows.create.p1": "推荐优先使用取单或复制类似工装借用，保证与上游数据一致。",
  "help.document.tool-borrows.create.s1": "点击新建旁下拉，选择空白新建或取单入口（若提供）。",
  "help.document.tool-borrows.create.s2": "在取单弹窗中筛选来源单据行，确认带入头行信息。",
  "help.document.tool-borrows.create.s3": "在表单中补全仓库、数量、日期等必填项，检查行单位与数量。",
  "help.document.tool-borrows.create.s4": "保存草稿供后续修改，或提交审核进入待审队列。",
  "help.document.tool-borrows.create.title": "5.1 新建与取单",
  "help.document.tool-borrows.detail.b1": "查看：只读打开详情，可查看关联链路。",
  "help.document.tool-borrows.detail.b2": "编辑：草稿或允许修改的状态下打开表单弹窗。",
  "help.document.tool-borrows.detail.b3": "审核/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.tool-borrows.detail.b4": "抽屉内可刷新单据，操作成功后列表与抽屉数据会同步更新。",
  "help.document.tool-borrows.detail.label": "5.6 详情抽屉与行操作",
  "help.document.tool-borrows.detail.p1": "点击行内「查看」或单号打开详情抽屉，集中阅读头信息、行项目与跟踪信息。",
  "help.document.tool-borrows.detail.title": "5.6 详情抽屉与行操作",
  "help.document.tool-borrows.faq.a1": "A: 常见原因：未选中单据、选中多条、未审核、目标模块未启用、无权限、行已无可推数量。请悬停按钮查看系统给出的具体原因。",
  "help.document.tool-borrows.faq.a2": "A: 表头按单据计数，明细按行项目计数，分页 total 不同属正常现象。",
  "help.document.tool-borrows.faq.a3": "A: 请使用组织配置的变更单、冲销或反审核流程，不要直接编辑已生效工装借用。",
  "help.document.tool-borrows.faq.a4": "A: 编码不存在、单位不匹配、必填为空、状态不合法等。请先维护主数据并下载最新模板。",
  "help.document.tool-borrows.faq.a5": "A: 明细视图按行展示且通常为只读，无行勾选；批量操作请在表头视图进行。",
  "help.document.tool-borrows.faq.a6": "A: 按钮受 RBAC 权限与单据 capability 双重控制；外协账号可能只见授权范围内的操作。",
  "help.document.tool-borrows.faq.q1": "Q: 为什么下推或审核按钮是灰的？",
