  "help.document.tool-repair-schemes.push.label": "5.4 下推与下游单据",
  "help.document.tool-repair-schemes.push.p1": "下推入口位于工具栏「下推」按钮（通常需选中恰好一条）或行内下推菜单。系统会先校验状态、剩余数量与模块是否启用。",
  "help.document.tool-repair-schemes.push.p2": "多数下推会先打开预览窗，展示可推数量与目标单据类型，确认后再生成下游单据。",
  "help.document.tool-repair-schemes.push.title": "5.4 下推与下游单据",
  "help.document.tool-repair-schemes.search.b1": "关键词：模糊匹配单号、编码、名称等主字段。",
  "help.document.tool-repair-schemes.search.b2": "伙伴/仓库/部门：按业务维度下拉筛选（若已配置）。",
