  "help.document.tool-repairs.lifecycle.auditB2": "待审核：等待审批人处理，通常不可直接下推。",
  "help.document.tool-repairs.lifecycle.auditB3": "已审核：可下推、可打印，修改需走正式变更通道。",
  "help.document.tool-repairs.lifecycle.auditP1": "是否启用多级审核由组织配置决定；行内按钮可能显示提交、通过、驳回、撤回等。",
  "help.document.tool-repairs.lifecycle.auditTitle": "审核相关",
