  "help.document.tool-scrap-applications.overview.p2": "本页面向业务操作人员：可在表头视图批量处理，在明细视图按行项目核对数量与状态。",
  "help.document.tool-scrap-applications.overview.title": "1. 概述",
  "help.document.tool-scrap-applications.push.alert": "下推按钮置灰时，将鼠标悬停可查看具体原因（未审核、模块未启用、无权限、无可推数量等）。",
