  "help.document.work-order.batch.p1": "批量按钮是否可用取决于选中行状态与您的权限码；灰色按钮悬停可查看原因。",
  "help.document.work-order.batch.title": "5.3 工具栏与批量操作",
  "help.document.work-order.create.b1": "空白新建：适用于试制或独立制造任务。",
  "help.document.work-order.create.b2": "导入：按模板批量创建，导入前请确认产品与工艺路线已在主数据存在。",
  "help.document.work-order.create.b3": "取单预览会展示 blocking 原因，不可推行需先处理上游单据。",
  "help.document.work-order.create.label": "5.1 新建与取单",
  "help.document.work-order.create.p1": "推荐优先使用取单，保证与上游计划或销售需求一致。",
  "help.document.work-order.create.s1": "点击新建旁下拉，选择「从需求计算取单」或「从销售订单取单」。",
  "help.document.work-order.create.s2": "在取单弹窗中筛选可推行，确认数量与下达模式（草稿或确认下达）。",
  "help.document.work-order.create.s3": "在表单中补全计划时间、工艺路线与工序分配，检查 BOM 与物料来源类型。",
  "help.document.work-order.create.s4": "保存草稿供后续修改，或确认后生成工单。",
  "help.document.work-order.create.title": "5.1 新建与取单",
  "help.document.work-order.detail.b1": "查看：只读打开详情，可复制单号、查看下推链路。",
  "help.document.work-order.detail.b2": "编辑：草稿状态下打开表单弹窗，可调整工序与计划。",
  "help.document.work-order.detail.b3": "下达/报工/打印/下推：与工具栏能力互补，适合单笔处理。",
  "help.document.work-order.detail.b4": "抽屉内可刷新单据，下达或下推成功后列表与抽屉数据会同步更新。",
  "help.document.work-order.detail.label": "5.6 详情抽屉与行操作",
  "help.document.work-order.detail.p1": "点击行内「查看」或工单号区域打开详情抽屉，集中阅读头信息、工序、物料移动与报工记录。",
  "help.document.work-order.detail.title": "5.6 详情抽屉与行操作",
  "help.document.work-order.faq.a1": "A: 常见原因：工单未下达、已冻结、未选中或选中多条、目标模块未启用、无下推权限、无可推数量。请悬停按钮查看具体原因。",
  "help.document.work-order.faq.a2": "A: 批量下达直接对选中草稿工单执行下达；智能下达会先预检齐套、交期与计划时间，仅对通过检查的工单批量下达，并展示未通过原因。",
  "help.document.work-order.faq.a3": "A: 树视图仅聚合当前筛选范围内的工单；请放宽筛选条件或确认是否存在对应产品/来源订单的工单。",
  "help.document.work-order.faq.a4": "A: 检查是否已下达、是否冻结，以及当前工序是否允许报工；外协工序通常在委外订单侧处理。",
  "help.document.work-order.faq.a5": "A: 点击新建旁「从销售订单取单」，在弹窗中选择可推行并确认数量；也可在销售合同页下推工单（若已启用）。",
  "help.document.work-order.faq.a6": "A: 冻结工单暂停报工与下推，需先解冻恢复执行态后再操作。",
  "help.document.work-order.faq.q1": "Q: 为什么下推按钮是灰的？",
  "help.document.work-order.faq.q2": "Q: 智能下达与批量下达有什么区别？",
  "help.document.work-order.faq.q3": "Q: 产品树/订单树视图为空？",
  "help.document.work-order.faq.q4": "Q: 工单无法报工？",
  "help.document.work-order.faq.q5": "Q: 如何从销售订单生成工单？",
  "help.document.work-order.faq.q6": "Q: 冻结后还能下推吗？",
  "help.document.work-order.guide.label": "5. 操作指南",
  "help.document.work-order.layout.b1": "指标卡：草稿、在制、逾期、待下达等关键数量；部分卡片可点击自动带入筛选。",
  "help.document.work-order.layout.b2": "工具栏左侧：新建/取单、下推（需先选中一条工单）；右侧：批量下达、智能下达、冻结/解冻、关单、导入导出等。",
  "help.document.work-order.layout.b3": "交期逾期行以警告底色标记，便于计划跟单。",
  "help.document.work-order.layout.b4": "列表列：工单号叠列产品、工序进度、下推进度、右侧固定状态与行操作。",
  "help.document.work-order.layout.label": "3. 页面布局",
  "help.document.work-order.layout.p1": "页面自上而下分为指标区、工具栏与列表区；右上角可切换表头/产品树/订单树/帮助视图。",
  "help.document.work-order.layout.title": "3. 页面布局",
  "help.document.work-order.lifecycle.auditB1": "草稿：可编辑、可删除（有权限时），尚未下达。",
  "help.document.work-order.lifecycle.auditB2": "已下达/在制：可报工、可下推，修改受限。",
  "help.document.work-order.lifecycle.auditB3": "已完工：完工数量已回写，可继续入库或检验流程。",
  "help.document.work-order.lifecycle.auditP1": "草稿工单需下达后车间方可报工；下达前系统可能校验齐套与计划时间。",
  "help.document.work-order.lifecycle.auditTitle": "下达与报工",
