  "help.document.work-order.lifecycle.title": "5.5 状态与执行",
  "help.document.work-order.overview.b1": "把销售或计划需求转化为可执行的制造任务。",
  "help.document.work-order.overview.b2": "通过下推衔接生产领料、成品检验、成品入库、生产退料与外协等下游流程。",
  "help.document.work-order.overview.b3": "支持智能下达批量：对选中工单预检齐套与交期风险后批量下达。",
  "help.document.work-order.overview.b4": "支持冻结与关单，控制异常工单继续报工或下推。",
