  "help.document.work-order.overview.p2": "本页面向计划员、车间主管与班组长：既要在表头视图批量下达与下推，也要在产品树/订单树视图按产品或来源订单追溯在制工单。",
  "help.document.work-order.overview.title": "1. 概述",
