  "help.document.work-order.push.b1": "生产领料：按 BOM 生成生产领料出库单。",
  "help.document.work-order.push.b2": "成品检验：生成成品检验单，检验合格后再入库。",
  "help.document.work-order.push.b3": "成品入库：完工数量入库过账。",
  "help.document.work-order.push.b4": "生产退料入库：退还未耗用物料。",
  "help.document.work-order.push.b5": "外协：按工序创建外协订单（行内「创建外协」入口）。",
  "help.document.work-order.push.b6": "下推前通常要求工单已下达且未冻结。",
